/** Real pinned source image/native registration with controlled divisions; no source configuration change. */
class RatisTopologyLearnerRuntimeTest {
    @TempDir(factory=RatisDiskTestDirectory.class) Path root;
    static Message message(byte[] bytes){return Message.valueOf(ByteString.copyFrom(bytes));}
    @Test void qualifiedListenerRegistrationIsForcedBeforeExposureAndColdRecoveryKeepsUserClosed()throws Exception {workflow(false,false,false);}
    @Test void unknownForceRetainsOriginalImageAndWitnessWhileActualSourcePinDrains()throws Exception {workflow(true,false,false);}
    @Test void equalSourceIndexWithDifferentCompletedTermCannotAuthorizeLearnerForce()throws Exception {workflow(false,true,false);}
    @Test void importedImageUnderActualSourceConfigurationIsOnlyImageEvidenceBeforeListenerCas()throws Exception {workflow(false,false,true);}
    private void workflow(boolean unknownForce,boolean crossedCut,boolean sourceConfiguration)throws Exception {
        var harness=new RatisTopologySeedRuntimeTest();harness.root=root.resolve("source");
        try(var source=harness.new Fixture()){
            var seed=source.node.seedTopology(source.request());var state=source.catalogueState;for(var target:source.definition.targets())state=state.seeded(seed.proof(target.groupId()));source.commit(state.publish());
            var range=source.definition.targets().getFirst();var machine=source.server.machines.get(RaftGroupId.valueOf(range.groupId()));RatisTopologySeedRuntimeTest.field(machine,"topologyAuthority",(RatisRangeStateMachine.TopologyAuthorityReader)source::authority);
            var activation=RatisTopologyActivationRecord.of(source.authority(source.definition.header(),TopologyChange.Stage.ACTIVATE),range.groupId());machine.queryLinearizable(message(RatisTopologyActivationRpc.prepareRequest(activation))).get(5,TimeUnit.SECONDS);
            var tx=machine.startTransaction(RaftClientRequest.newBuilder().setClientId(ClientId.randomId()).setServerId(RaftPeerId.valueOf(source.plan.peerId())).setGroupId(RaftGroupId.valueOf(range.groupId())).setCallId(1).setType(RaftClientRequest.writeRequestType()).setMessage(message(activation.encode())).build());assertNull(tx.getException());machine.preAppendTransaction(tx);var donor=RatisTopologySeedRuntimeTest.field(machine,"store",ReplicatedRangeStore.class);tx.initLogEntry(1,donor.applied().index()+1);machine.applyTransaction(tx).get(5,TimeUnit.SECONDS);
            var remote=source.plan.catalogue().replicas().getFirst();var receiver=new ReplicaDescriptor(remote.nodeId(),remote.nodeIncarnation(),new UUID(110,1),remote.peerId(),remote.address(),ReplicaDescriptor.Role.LISTENER);var replicas=new ArrayList<>(range.replicas());replicas.add(receiver);var target=new RangeDescriptor(range.rangeId(),range.groupId(),range.rangeEpoch(),range.configurationVersion()+1,range.lowerInclusive(),range.upperExclusive(),range.topologyState(),replicas);var original=source.definition.targetDirectory();var next=new RangeDirectory(original.clusterId(),original.databaseId(),original.domainId(),original.schemaEpoch(),original.schemaDigest(),original.generation()+1,original.columns(),original.routingPrefixBytes(),List.of(target,original.ranges().getLast()));var relocation=new TopologyChange.Definition(new UUID(110,2),original,next);var prepared=TopologyChange.State.begin(relocation.header());
            var domain=ByteBuffer.allocate(16).putLong(original.domainId().getMostSignificantBits()).putLong(original.domainId().getLeastSignificantBits()).array();var catalogue=source.env.catalogue.store;var column=source.env.outer.directoryColumn;
            var metadata=new DistributedCommand(source.env.outer.catalogue,1,new byte[32],new OperationId(new UUID(110,3),1,0),List.of(new Mutation(Mutation.Kind.PUT,column,RatisTopologyCatalogue.definitionKey(relocation.digest()),relocation.encode()),new Mutation(Mutation.Kind.PUT,column,RatisTopologyCatalogue.headKey(original.domainId()),prepared.encode()),new Mutation(Mutation.Kind.PUT,column,RatisTopologyCatalogue.stateKey(relocation.intentId()),prepared.encode()),new Mutation(Mutation.Kind.PUT,column,domain,RangeDirectoryCodec.encode(original))));assertEquals(CommandResult.Status.SUCCESS,CommandResult.decode(catalogue.apply(new ApplyPosition(1,source.env.catalogue.next.getAndIncrement()),metadata)).status());
            var request=RatisTopologyJoinAuthority.Request.of(relocation,receiver.replicaId());var view=RatisTopologyJoinAuthority.readNative(catalogue,column,original.clusterId(),original.databaseId(),request);assertEquals(receiver,view.require(request));assertArrayEquals(relocation.encode(),RatisTopologyJoinAuthority.decodeReply(RatisTopologyJoinAuthority.reply(view),request,view.catalogue()).definition().encode());assertThrows(IllegalArgumentException.class,()->view.require(RatisTopologyJoinAuthority.Request.of(relocation,source.local.replicaId())));
            var plan=new RatisNodePlan(receiver.nodeId(), receiver.nodeIncarnation(), List.of(new RatisNodePlan.Domain(original, source.plan.columns(), source.plan.merges())), source.plan.catalogue(), List.of(), List.of(), Map.of(), 16,RatisPoolFixtures.pools(),RatisPoolFixtures.domains(List.of(new RatisNodePlan.Domain(original, source.plan.columns(), source.plan.merges()))),RatisPoolFixtures.groups(source.plan.catalogue(),List.of()));var routed=new RatisRoutedClient(original,new RatisRoutedClient.Transport(){public byte[] read(RangeDescriptor r,UUID c,byte[] k){throw new AssertionError();}public CommandResult command(RangeDescriptor r,DistributedCommand c){throw new AssertionError();}});var receiverRoot=java.nio.file.Files.createDirectories(root.resolve("receiver"));var fake=new RatisNodeRuntimeTest.FakeServer();
            var node=RatisNodeRuntime.open(plan, receiverRoot, ConfigParser.parseDefault(), source.env.catalogue.epochs, Map.of(routed.directory().domainId(), routed), source.env.scheduler, source.env.timer, ()->20L, source.env.settings(), RatisNodeRuntime.Startup.AUTHORIZED_INITIAL_PLACEMENT, fake::create, List.of(RatisTopologySeedRuntimeTest.schema()));
            RatisTopologySeedRuntimeTest.field(node,"joinAuthority",(RatisNodeRuntime.JoinAuthorityReader)r->RatisTopologyJoinAuthority.readNative(catalogue,column,original.clusterId(),original.databaseId(),r));
            if(crossedCut)for(long index=donor.applied().index()+1;index<=5;index++)machine.notifyTermIndexUpdated(1,index);
            var sourceReads=new java.util.concurrent.atomic.AtomicInteger();var pinEntered=new java.util.concurrent.CountDownLatch(1);var releasePin=new java.util.concurrent.CountDownLatch(unknownForce?1:0);
            node.learnerSource((authority,local)->{sourceReads.incrementAndGet();try(var pin=donor.captureForRecovery()){pinEntered.countDown();if(!releasePin.await(5,TimeUnit.SECONDS))throw new java.io.IOException("Source pin release timed out");var image=NativeRangeImage.write(root.resolve("learner.image"),pin,pin.interval(),source.env.settings().images());var schemaRows=new HashMap<String,byte[]>();pin.visitState((key,value)->{if(NativeTopologyLearnerSchema.row(key))schemaRows.put(HexFormat.of().formatHex(key),value.clone());});return new RatisNodeRuntime.LearnerSourceEvidence(image,RatisTopologySeedRuntimeTest.schema(),source.local,pin.configuration(),crossedCut?new ApplyPosition(2,5):donor.applied(),source.plan.columns(),source.plan.merges(),schemaRows);}catch(Exception failure){throw new java.io.IOException(failure);}});
            try{node.start();var pool=node.nativePool(RatisPoolFixtures.ID);byte[] attempted=null;
                if(crossedCut){assertEquals(new ApplyPosition(1,5),donor.applied());var rejectingNode=node;assertThrows(java.io.IOException.class,()->rejectingNode.joinTopologyLearner(request));assertTrue(pool.topologyLearners().isEmpty());assertNull(RatisTopologySeedRuntimeTest.field(node,"learnerAttempt",NativeTopologyLearnerRegistration.class));assertTrue(node.localGroups().stream().noneMatch(g->g.getGroupId().getUuid().equals(range.groupId())));assertFalse(fake.storages.containsKey(RaftGroupId.valueOf(range.groupId())));assertEquals(1,sourceReads.get());assertEquals(0,donor.activeSnapshotPins());return;}

                if(unknownForce){var once=new java.util.concurrent.atomic.AtomicBoolean(true);pool.topologyLearnerForceObserver(after->{if(after && once.compareAndSet(true,false))throw new org.rocksdb.RocksDBException("Lost learner force reply");});var originalNode=node;try(var executor=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var joining=executor.submit(()->originalNode.joinTopologyLearner(request));assertTrue(pinEntered.await(5,TimeUnit.SECONDS));try{assertEquals(1,donor.activeSnapshotPins());assertThrows(java.io.IOException.class,originalNode::close);}finally{releasePin.countDown();}assertThrows(java.util.concurrent.ExecutionException.class,()->joining.get(5,TimeUnit.SECONDS));}assertEquals(0,donor.activeSnapshotPins());assertTrue(pool.topologyLearners().isEmpty());var attempt=RatisTopologySeedRuntimeTest.field(node,"learnerAttempt",NativeTopologyLearnerRegistration.class);attempted=attempt.encode();assertTrue(java.nio.file.Files.isRegularFile(root.resolve("learner.image")));assertThrows(java.io.IOException.class,()->originalNode.joinTopologyLearner(RatisTopologyJoinAuthority.Request.of(relocation,source.local.replicaId())));var changedReceiver=new ReplicaDescriptor(receiver.nodeId(),new UUID(110,9),receiver.replicaId(),receiver.peerId(),receiver.address(),receiver.role());var changedTarget=new RangeDescriptor(target.rangeId(),target.groupId(),target.rangeEpoch(),target.configurationVersion(),target.lowerInclusive(),target.upperExclusive(),target.topologyState(),List.of(source.local,changedReceiver));var changedDirectory=new RangeDirectory(next.clusterId(),next.databaseId(),next.domainId(),next.schemaEpoch(),next.schemaDigest(),next.generation(),next.columns(),next.routingPrefixBytes(),List.of(changedTarget,next.ranges().getLast()));var changed=new TopologyChange.Definition(relocation.intentId(),original,changedDirectory);assertThrows(java.io.IOException.class,()->originalNode.joinTopologyLearner(RatisTopologyJoinAuthority.Request.of(changed,receiver.replicaId())));machine.notifyTermIndexUpdated(1,donor.applied().index()+1);}
                var registration=node.joinTopologyLearner(request);if(attempted!=null)assertArrayEquals(attempted,registration.encode());assertEquals(1,sourceReads.get());assertNull(RatisTopologySeedRuntimeTest.field(node,"learnerAttempt",NativeTopologyLearnerRegistration.class));assertEquals(registration,pool.topologyLearners().getFirst());var learnerMachine=fake.machines.get(RaftGroupId.valueOf(range.groupId()));var learner=RatisTopologySeedRuntimeTest.field(learnerMachine,"store",ReplicatedRangeStore.class);assertTrue(learner.topologyBirthPending());assertFalse(learner.admissionOpen());assertThrows(IllegalStateException.class,()->learner.capture());assertFalse(learnerMachine.topologyLearnerReadiness(registration.imageCut()).ready());
                if(sourceConfiguration){
                    var joining=prepared.beginJoining();var progress=new DistributedCommand(source.env.outer.catalogue,1,new byte[32],new OperationId(new UUID(110,4),1,0),List.of(new Mutation(Mutation.Kind.PUT,column,RatisTopologyCatalogue.headKey(original.domainId()),joining.encode()),new Mutation(Mutation.Kind.PUT,column,RatisTopologyCatalogue.stateKey(relocation.intentId()),joining.encode())));assertEquals(CommandResult.Status.SUCCESS,CommandResult.decode(catalogue.apply(new ApplyPosition(1,source.env.catalogue.next.getAndIncrement()),progress)).status());
                    RatisTopologySeedRuntimeTest.field(learnerMachine,"relocationAuthority",(RatisRangeStateMachine.RelocationAuthorityReader)r->RatisTopologyJoinAuthority.readNative(catalogue,column,original.clusterId(),original.databaseId(),r));
                    // Receiver recovery validates the registered source provenance, not an invented receiver-local seed.
                    var validation=RatisRangeStateMachine.class.getDeclaredMethod("validateImage",Path.class,org.apache.ratis.server.protocol.TermIndex.class);validation.setAccessible(true);
                    var validated=(NativeRangeImage.Manifest)validation.invoke(learnerMachine,root.resolve("learner.image"),org.apache.ratis.server.protocol.TermIndex.valueOf(registration.imageCut().term(),registration.imageCut().index()));assertArrayEquals(registration.imageHash(),validated.sha256());
                    learner.installSnapshot(root.resolve("learner.image"),source.env.settings().images());assertTrue(learner.topologyLearnerImageInstalled());
                    // The actual Ratis sender includes its SOURCE configuration; receiver updateConfiguration adopts it.
                    var proto=org.apache.ratis.proto.RaftProtos.RaftConfigurationProto.parseFrom(registration.sourceConfiguration());var peers=new ArrayList<RaftPeer>();peers.addAll(org.apache.ratis.util.ProtoUtils.toRaftPeers(proto.getPeersList()));for(var peer:org.apache.ratis.util.ProtoUtils.toRaftPeers(proto.getListenersList()))peers.add(RaftPeer.newBuilder(peer).setStartupRole(org.apache.ratis.proto.RaftProtos.RaftPeerRole.LISTENER).build());fake.actualGroups.put(RaftGroupId.valueOf(range.groupId()),RaftGroup.valueOf(RaftGroupId.valueOf(range.groupId()),peers));
                    var imageRequest=new RatisRelocationOwnerRpc.Request(relocation,receiver.replicaId(),RatisRelocationOwnerRpc.Expected.IMAGE,registration.imageCut(),registration.imageHash());var reply=learnerMachine.query(message(RatisRelocationOwnerRpc.request(imageRequest))).get(5,TimeUnit.SECONDS);var evidence=RatisRelocationOwnerRpc.decodeReply(reply.getContent().toByteArray(),imageRequest);assertTrue(evidence.imageInstalled());assertFalse(evidence.caughtUp());assertFalse(learner.admissionOpen());
                    var targetRequest=new RatisRelocationOwnerRpc.Request(relocation,receiver.replicaId(),RatisRelocationOwnerRpc.Expected.TARGET,registration.imageCut(),null);assertThrows(java.util.concurrent.ExecutionException.class,()->learnerMachine.query(message(RatisRelocationOwnerRpc.request(targetRequest))).get(5,TimeUnit.SECONDS));return;
                }
assertArrayEquals(registration.encode(),node.joinTopologyLearner(request).encode());assertEquals(org.apache.ratis.proto.RaftProtos.RaftPeerRole.LISTENER,node.localGroups().stream().filter(g->g.getGroupId().getUuid().equals(range.groupId())).findFirst().orElseThrow().getPeers().stream().filter(p->p.getId().toString().equals(receiver.peerId())).findFirst().orElseThrow().getStartupRole());node.close();
                fake=new RatisNodeRuntimeTest.FakeServer();node=RatisNodeRuntime.open(plan, receiverRoot, ConfigParser.parseDefault(), source.env.catalogue.epochs, Map.of(routed.directory().domainId(), routed), source.env.scheduler, source.env.timer, ()->20L, source.env.settings(), RatisNodeRuntime.Startup.RECOVER, fake::create, List.of(RatisTopologySeedRuntimeTest.schema()));node.start();assertArrayEquals(registration.encode(),node.joinTopologyLearner(request).encode());assertTrue(RatisTopologySeedRuntimeTest.field(fake.machines.get(RaftGroupId.valueOf(range.groupId())),"store",ReplicatedRangeStore.class).topologyBirthPending());
            }finally{node.close();routed.close();}
        }
    }
}
